<script setup lang="ts">
import {ref} from 'vue';import {onLoad,onShow,onHide} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {money,currentCurrency} from '@shared/utils/money';import {ApiError} from '@shared/net/http-client';import {managementTime} from '@/shared/management';import type {SvSummary,SvStoreAttribution} from '@/api/stored-value-finance';
const {t}=useI18n();const m=ref(''),brand=ref(''),store=ref(''),activity=ref('');const currency=currentCurrency();const today=new Date();const date=(d:Date)=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const from=ref(date(new Date(today.getFullYear(),today.getMonth(),1))),to=ref(date(new Date(today.getFullYear(),today.getMonth(),today.getDate()+1)));
const summary=ref<SvSummary|null>(null),rows=ref<SvStoreAttribution[]>([]),next=ref<string|null>(null);const loading=ref(true),failed=ref(false),unavailable=ref(false),dates=ref(false),error=ref('');
let generation=0;
const q=()=>({managementNo:m.value,currency,startDate:from.value,endDate:to.value,...(activity.value?{activityNo:activity.value}:{})});
async function load(){const run=++generation;const query=q();loading.value=true;failed.value=false;unavailable.value=false;error.value='';try{const value=await (brand.value?api.mSvBrandSummary(brand.value,query):api.mSvStoreSummary(store.value,query));if(run!==generation)return;summary.value=value;if(brand.value){const p=await api.mSvBrandStoreBreakdown(brand.value,query);if(run!==generation)return;rows.value=p.records;next.value=p.nextCursor}}catch(e){if(run===generation){if(e instanceof ApiError&&e.code===10404){summary.value=null;rows.value=[];next.value=null;unavailable.value=true}else{failed.value=true;error.value=(e as Error).message}}}finally{if(run===generation)loading.value=false}}
async function more(){if(!next.value||loading.value)return;const run=generation;try{const p=await api.mSvBrandStoreBreakdown(brand.value,{...q(),cursor:next.value});if(run!==generation)return;rows.value.push(...p.records);next.value=p.nextCursor}catch(e){if(run===generation)error.value=(e as Error).message}}

function apply(){dates.value=false;void load()}
onLoad(q=>{m.value=q?.m||'';brand.value=q?.b||'';store.value=q?.s||'';activity.value=q?.activity||'';void load()});
onShow(()=>{if(m.value&&!loading.value)void load()});onHide(()=>{generation++;summary.value=null;rows.value=[];next.value=null;loading.value=false});
</script>
<template><sh-scaffold title-key="svFinance.summary" :pending="loading" :failed="failed" :failed-text="error" @retry="load">
 <view class="sh-card sh-row sh-row--between" @tap="dates=true"><text>{{from}} — {{to}}</text><sh-go/></view>
 <sh-empty v-if="unavailable" :text="t('svFinance.noReportData')"/>
 <template v-if="summary"><view class="sh-card"><text class="txt-title">{{summary.name}}</text><text class="sh-chip">{{t(brand?'issuer.brandScope':'issuer.storeScope')}}</text><sh-kv v-for="key in (['openingMinor','creditedPaidMinor','creditedBonusMinor','consumedMinor','reversedMinor','closingMinor','heldMinor','payableMinor'] as const)" :key="key" :label="t('svFinance.'+key)" between>{{money(summary[key],summary.currency)}}</sh-kv><sh-kv v-for="key in (['rechargeCount','usageCount','customerCount'] as const)" :key="key" :label="t('svFinance.'+key)" between>{{summary[key]}}</sh-kv><text class="txt-sub sh-muted">{{t('svFinance.asOf')}} {{managementTime(summary.asOf)}}</text></view>
 <view v-for="row in rows" :key="row.storeNo" class="sh-card"><text class="txt-strong">{{row.storeName}}</text><sh-kv :label="t('svFinance.creditedPaidMinor')" between>{{money(row.creditedPaidMinor,currency)}}</sh-kv><sh-kv :label="t('svFinance.creditedBonusMinor')" between>{{money(row.creditedBonusMinor,currency)}}</sh-kv><sh-kv :label="t('svFinance.consumedMinor')" between>{{money(row.consumedMinor,currency)}}</sh-kv><sh-kv :label="t('svFinance.payableMinor')" between>{{money(row.payableMinor,currency)}}</sh-kv></view><view v-if="next" class="sh-btn sh-btn--soft" @tap="more">{{t('svGov.more')}}</view></template>
 <text v-if="error" class="sh-hint">{{error}}</text><sh-sheet :visible="dates" :title="t('svFinance.period')" @close="dates=false"><view class="sh-card"><picker mode="date" :value="from" @change="from=$event.detail.value"><view class="sh-cell">{{t('svGov.startDate')}} · {{from}}</view></picker><picker mode="date" :value="to" @change="to=$event.detail.value"><view class="sh-cell">{{t('svFinance.endExclusive')}} · {{to}}</view></picker></view><view class="sh-btn" @tap="apply">{{t('svFinance.query')}}</view></sh-sheet>
</sh-scaffold></template>
